// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
import "@openzeppelin/contracts/token/ERC721/ERC721.sol";

/// @title AnimVoiceLedger
/// @notice ERC-721 provenance mint for: Mint voice acting performances as NFTs proving rights and enabling royalty tracking.
